package com.hmdp.ai.application.dto.knowledge;
import com.hmdp.ai.domain.artifact.Citation;import com.hmdp.ai.domain.knowledge.RetrievedChunk;import java.util.Map;
public final class RetrievedChunkResponse {private final String chunkId,documentId,knowledgeBaseId,section,text;private final int documentVersion;private final Integer page;private final double score,vectorScore,lexicalScore,rerankScore;private final Map<String,Object> metadata;private final Citation citation;public RetrievedChunkResponse(RetrievedChunk v){chunkId=v.getChunk().getId();documentId=v.getChunk().getDocumentId();documentVersion=v.getChunk().getDocumentVersion();knowledgeBaseId=v.getChunk().getKnowledgeBaseId();page=v.getChunk().getPage();section=v.getChunk().getSection();score=v.getScore();vectorScore=v.getVectorScore();lexicalScore=v.getLexicalScore();rerankScore=v.getRerankScore();text=v.getText();metadata=v.getMetadata();citation=v.getCitation();}public String getChunkId(){return chunkId;}public String getDocumentId(){return documentId;}public int getDocumentVersion(){return documentVersion;}public String getKnowledgeBaseId(){return knowledgeBaseId;}public Integer getPage(){return page;}public String getSection(){return section;}public double getScore(){return score;}public double getVectorScore(){return vectorScore;}public double getLexicalScore(){return lexicalScore;}public double getRerankScore(){return rerankScore;}public String getText(){return text;}public Map<String,Object> getMetadata(){return metadata;}public Citation getCitation(){return citation;}}
